document.querySelectorAll('.nav-btn[data-tab]').forEach(b => {
  const t = b.dataset.tab;
  const inProf = prof.tabs === 'all' || (Array.isArray(prof.tabs) && prof.tabs.includes(t));
  // Platform Invoices: show whenever the account is allowed (e.g. John), even in operator workspace
  const show = (t === 'home' || (name === 'accountant' && t === 'perf') || inProf || t === 'platinv') && (typeof accTab !== 'function' || accTab(t));
  b.style.display = show ? '' : 'none';
});
